const captures = new WeakMap();
let nextCapture = null;
function diagnose(capture, action) {
	if (capture.failure) return;
	try {
		action();
	} catch (error) {
		// Even a hostile/unprintable diagnostic error cannot replace a game error.
		capture.failure = "Erosion observation failed";
		try {
			capture.failure = String(error) || capture.failure;
		} catch {}
	}
}
function snapshot(land, erosion, game) {
	if (!(land.heights instanceof Int16Array) || land.heights.length !== 16384) throw new Error("Erosion observation requires all 16384 native signed heights");
	return {
		center: { ...erosion.center },
		remaining: erosion.remaining,
		randomState: game.randomState,
		heights: new Int16Array(land.heights)
	};
}
// A diagnostic handle owns only copies. Its registration changes neither the
// controller nor World; the browser driver must prove ordinary onset separately.
function captureHandle(capture) {
	return {
		status: () => ({
			count: capture.visits.length,
			failure: capture.failure
		}),
		read: () => structuredClone(capture),
		detach: () => {
			capture.detached = true;
			// Keep the weak registration to reject re-arming the same controller.
		}
	};
}
export function armErosionCapture(erosion) {
	if (erosion.remaining !== 64 || captures.has(erosion)) throw new Error("Erosion capture requires a new, unobserved controller at remaining 64");
	const capture = {
		visits: [],
		failure: null,
		detached: false
	};
	captures.set(erosion, capture);
	return captureHandle(capture);
}
// Ordinary capture declares its target before creation. It never searches for a
// replacement, calls a user callback or gives the observer a live controller.
export function declareNextErosionCapture(expected) {
	if (nextCapture) {
		nextCapture.capture.failure = "An Erosion capture declaration is already active";
		throw new Error(nextCapture.capture.failure);
	}
	const { x, y } = expected;
	if (![x, y].every((value) => Number.isInteger(value) && value >= 0 && value <= 65535)) throw new Error("Erosion declaration requires unsigned native coordinates");
	const capture = {
		visits: [],
		failure: null,
		detached: false
	}, declaration = {
		expected: {
			x,
			y
		},
		controller: null,
		creation: null,
		creations: 0,
		capture
	}, handle = captureHandle(capture);
	nextCapture = declaration;
	return {
		status: () => ({
			...handle.status(),
			created: declaration.controller !== null
		}),
		read: () => ({
			...handle.read(),
			creation: structuredClone(declaration.creation)
		}),
		matches: (controller) => !capture.detached && capture.failure === null && declaration.controller === controller,
		detach: () => {
			handle.detach();
			if (nextCapture === declaration) nextCapture = null;
		}
	};
