// Internal constructor notification, before its exact new object is returned.
// Diagnostics can fail, but may never change creation or its caller's first step.
export function recordErosionCreation(erosion) {
	const declaration = nextCapture;
	if (!declaration) return;
	diagnose(declaration.capture, () => {
		if (++declaration.creations !== 1) throw new Error("Unexpected second Erosion creation during the declared capture");
		if (erosion.center.x !== declaration.expected.x || erosion.center.y !== declaration.expected.y || erosion.remaining !== 64 || captures.has(erosion)) throw new Error("The next Erosion creation did not match its declared target");
