	const current = visit;
	const notify = (notification, action) => {
		diagnose(capture, () => current.notifications.push(notification));
		const result = action();
		notification.completed = true;
		return result;
	};
	try {
		const alive = step(land, erosion, game, {
			sound: () => notify({
				kind: "sound",
				completed: false
			}, () => effects.sound()),
			terrain: (cell) => notify({
				kind: "terrain",
				cell,
				completed: false
			}, () => effects.terrain(cell))
