				version: 2,
				kind: "ordinary-m3-erosion-controller-inputs",
				...structuredClone(identity),
				level: 3,
				shrineId: 101,
				effectId: effect.id,
				onsetTurn,
				failure: null,
				detached: true,
				creation: capture.creation,
				steps: capture.visits.map((visit, index) => ({
					turn: turns[index],
					visit: {
						...visit,
						before: {
							...visit.before,
							heights: Array.from(visit.before.heights)
						},
						after: visit.after && {
