		progress: () => structuredClone(epoch),
		complete: () => !!epoch.erosion.effects[0]?.retired && !epoch.errors.length && !epoch.speedViolations.length,
		read: () => ({
			capture: capture.read(),
			lifecycle: structuredClone(epoch)
