		const context = liveCommandContext(probe, point);
		return {
			model: context?.model ?? null,
			enabled: context?.enabled === true,
			buildingId: context?.building?.id ?? null,
			personId: context?.person?.id ?? null,
			shrineId: context?.shrine?.id ?? null,
			treeId: context?.tree?.id ?? null,
			vehicleId: context?.vehicle?.id ?? null
